    "apiSignature": "function AiChat(props: AiChatProps): JSX.Element\ninterface AiChatProps { folders?: AiChatFolder[]; threads?: AiChatThread[]; files?: AiChatFile[]; defaultThreadId?: string; autoStart?: boolean; className?: string }",
