    "apiSignature": "export function AppointmentsListCard({ appointments, defaultAppointments = [], onAppointmentsChange, onReschedule, onCancel, onRestore, getSlots = defaultSlots, title = \"Upcoming appointments\", countLabel = \"scheduled\", locale = \"en-US\", className }: AppointmentsListCardProps): JSX.Element",
