    "apiSignature": "function DocsCallout(props: { variant?: \"info\" | \"tip\" | \"warning\" | \"danger\"; title?: ReactNode; children?: ReactNode; icon?: IconComponent | null; dismissible?: boolean; onDismiss?: () => void; dismissLabel?: string; className?: string }): JSX.Element | null",
