    "apiSignature": "function Drawer(props: Omit<ModalOverlayProps, \"children\" | \"className\" | \"style\"> & { placement?: \"start\" | \"end\" | \"top\" | \"bottom\"; size?: \"sm\" | \"md\" | \"lg\"; \"aria-label\"?: string; className?: string; overlayClassName?: string; children: ReactNode | ((renderProps: DialogRenderProps) => ReactNode) }): JSX.Element\nexport { ModalBody as DrawerBody, ModalFooter as DrawerFooter, ModalHeader as DrawerHeader, ModalTrigger as DrawerTrigger }",
