    "apiSignature": "function ModelsPicker(props: ({ selectionMode?: \"single\"; value?: string; defaultValue?: string; onChange?: (id: string) => void } | { selectionMode: \"multiple\"; value?: string[]; defaultValue?: string[]; onChange?: (ids: string[]) => void }) & { models: ModelOption[]; label?: ReactNode; searchable?: boolean; searchPlaceholder?: string; children?: ReactNode; className?: string }): JSX.Element\ntype ModelOption = { id: string; name: string; provider: string; monogram?: string; tone?: ModelMonogramTone; description?: string; isDisabled?: boolean }",
