    "apiSignature": "export function NotificationBellBadge({ notifications, defaultNotifications, onNotificationsChange, isOpen, defaultOpen, onOpenChange, max, size, label, emptyState, footer, placement, className, popoverClassName }: NotificationBellBadgeProps): JSX.Element\nexport function BellButton({ count, max, size, label, className, ref, ...props }: BellButtonProps): JSX.Element",
