    "apiSignature": "function RadialChartCard(props: { title?: string; variant?: \"rings\" | \"labels\" | \"grid\" | \"gauge\"; ranges?: RadialRange[]; items?: RadialItem[]; delta?: number; max?: number; range?: string; defaultRange?: string; onRangeChange?: (id: string) => void; tiles?: boolean; showCenter?: boolean; gaugeCaption?: string; formatValue?: (value: number) => string; className?: string }): JSX.Element\ntype RadialItem = { label: string; value: number; color?: ChartColor }\ntype RadialRange = { id: string; label: string; items: RadialItem[]; delta?: number; goal?: number }",
