    "apiSignature": "export function TableFilterBar({ filters, values, defaultValues, onValuesChange, query, defaultQuery, onQueryChange, searchPlaceholder, resultCount, resultLabel, totalLabel, showActiveFilters, clearLabel, className }: TableFilterBarProps): JSX.Element",
