    "apiSignature": "function TechBadgesRow(props: { badges?: TechBadge[]; variant?: \"label\" | \"icon\"; label?: string; className?: string }): JSX.Element\ntype TechBadge = { id: string; name: string; version?: string; monogram: string; tone: string; description?: string }",
